// socTop: demonstration SoC built around the networkOnChip project.
//
// A PicoRV32 RISC-V CPU (AXI4-Lite master) is the only initiator on a 2x2
// mesh NoC (nocSoc, generated by networkOnChip/autoConfiguration/nocGen.py
// from config/socNoc.json). The NoC routes each CPU access by address to one
// of three targets, each on its own router:
//
//   0x0000_0000 - 0x0000_3FFF  ram   AXI4-Lite SRAM (boot image, stack, data)
//   0x4000_0000 - 0x4000_0FFF  timer PULP apb_timer (2 timers)
//   0x4000_1000 - 0x4000_1FFF  gpio  PULP apb_gpio (32 pads)
//
// The CPU boots from address 0, so every instruction fetch crosses the mesh.
// AXI4-Lite to APB conversion for the timer and GPIO happens in the NoC's
// target bridges. Three clock domains are used: cpu (CPU and its NI), fabric
// (mesh and RAM) and periph (timer and GPIO); the NoC inserts the CDC
// bridges. Resets are expected to be synchronised to their own clock
// externally.

`default_nettype none

module socTop
( input  var logic        i_cpuClk
, input  var logic        i_cpuArst_n
, input  var logic        i_fabricClk
, input  var logic        i_fabricArst_n
, input  var logic        i_periphClk
, input  var logic        i_periphArst_n

, output var logic        o_cpuTrap

, input  var logic [31:0] i_gpioIn
, output var logic [31:0] o_gpioOut
, output var logic [31:0] o_gpioDir
, output var logic        o_gpioInterrupt

, output var logic [3:0]  o_timerIrq
);

  // {{{ CPU
  // PicoRV32 in its AXI4-Lite master variant, RV32I with no IRQs or
  // co-processor. It resets to the start of RAM with the stack pointer
  // preset just below the console mailbox at the top of RAM. PicoRV32
  // ignores BRESP/RRESP and the AxPROT outputs have no NoC equivalent.

  logic [31:0] cpuAwaddr;
  logic        cpuAwvalid;
  logic        cpuAwready;
  logic [31:0] cpuWdata;
  logic [3:0]  cpuWstrb;
  logic        cpuWvalid;
  logic        cpuWready;
/* verilator lint_off UNUSEDSIGNAL */
  logic [1:0]  cpuBresp;
/* verilator lint_on UNUSEDSIGNAL */
  logic        cpuBvalid;
  logic        cpuBready;
  logic [31:0] cpuAraddr;
  logic        cpuArvalid;
  logic        cpuArready;
  logic [31:0] cpuRdata;
/* verilator lint_off UNUSEDSIGNAL */
  logic [1:0]  cpuRresp;
/* verilator lint_on UNUSEDSIGNAL */
  logic        cpuRvalid;
  logic        cpuRready;

/* verilator lint_off PINCONNECTEMPTY */
  // o_cpuTrap is asserted when the core hits a fault it can't handle and halts
  // permanently.
  picorv32_axi
  #(.ENABLE_COUNTERS ('0)
  , .ENABLE_IRQ      ('0)
  , .COMPRESSED_ISA  ('0)
  , .PROGADDR_RESET  (32'h0000_0000)
  , .STACKADDR       (32'h0000_3FF0)
  ) u_cpu
  ( .clk             (i_cpuClk)
  , .resetn          (i_cpuArst_n)
  , .trap            (o_cpuTrap)

  , .mem_axi_awvalid (cpuAwvalid)
  , .mem_axi_awready (cpuAwready)
  , .mem_axi_awaddr  (cpuAwaddr)
  , .mem_axi_awprot  ()

  , .mem_axi_wvalid  (cpuWvalid)
  , .mem_axi_wready  (cpuWready)
  , .mem_axi_wdata   (cpuWdata)
  , .mem_axi_wstrb   (cpuWstrb)

  , .mem_axi_bvalid  (cpuBvalid)
  , .mem_axi_bready  (cpuBready)

  , .mem_axi_arvalid (cpuArvalid)
  , .mem_axi_arready (cpuArready)
  , .mem_axi_araddr  (cpuAraddr)
  , .mem_axi_arprot  ()

  , .mem_axi_rvalid  (cpuRvalid)
  , .mem_axi_rready  (cpuRready)
  , .mem_axi_rdata   (cpuRdata)

  , .pcpi_valid      ()
  , .pcpi_insn       ()
  , .pcpi_rs1        ()
  , .pcpi_rs2        ()
  , .pcpi_wr         ('0)
  , .pcpi_rd         ('0)
  , .pcpi_wait       ('0)
  , .pcpi_ready      ('0)

  , .irq             ('0)
  , .eoi             ()

  , .trace_valid     ()
  , .trace_data      ()
  );
/* verilator lint_on PINCONNECTEMPTY */

  // }}} CPU

  // {{{ RAM
  // Boot/data SRAM on the fabric clock, 4096 words (16 KiB) to match the
  // NoC address map entry.

  logic [31:0] ramAwaddr;
  logic        ramAwvalid;
  logic        ramAwready;
  logic [31:0] ramWdata;
  logic [3:0]  ramWstrb;
  logic        ramWvalid;
  logic        ramWready;
  logic [1:0]  ramBresp;
  logic        ramBvalid;
  logic        ramBready;
  logic [31:0] ramAraddr;
  logic        ramArvalid;
  logic        ramArready;
  logic [31:0] ramRdata;
  logic [1:0]  ramRresp;
  logic        ramRvalid;
  logic        ramRready;

  axiLiteSram
  #(.DEPTH (4096)
  ) u_ram
  ( .i_clk     (i_fabricClk)
  , .i_arst_n  (i_fabricArst_n)

  , .i_awaddr  (ramAwaddr)
  , .i_awvalid (ramAwvalid)
  , .o_awready (ramAwready)
  , .i_wdata   (ramWdata)
  , .i_wstrb   (ramWstrb)
  , .i_wvalid  (ramWvalid)
  , .o_wready  (ramWready)
  , .o_bresp   (ramBresp)
  , .o_bvalid  (ramBvalid)
  , .i_bready  (ramBready)

  , .i_araddr  (ramAraddr)
  , .i_arvalid (ramArvalid)
  , .o_arready (ramArready)
  , .o_rdata   (ramRdata)
  , .o_rresp   (ramRresp)
  , .o_rvalid  (ramRvalid)
  , .i_rready  (ramRready)
  );

  // }}} RAM

  // {{{ Timer
  // PULP apb_timer with two 32-bit timers on the periph clock. It decodes
  // only the 4 KiB page offset; the NoC has already selected the page. Its
  // registers are word-wide so PSTRB is not needed.

/* verilator lint_off UNUSEDSIGNAL */
  logic [31:0] timerPaddr;
  logic [3:0]  timerPstrb;
/* verilator lint_on UNUSEDSIGNAL */
  logic [31:0] timerPwdata;
  logic        timerPwrite;
  logic        timerPsel;
  logic        timerPenable;
  logic        timerPready;
  logic        timerPslverr;
  logic [31:0] timerPrdata;

  apb_timer
  #(.APB_ADDR_WIDTH (12)
  , .TIMER_CNT      (2)
  ) u_timer
  ( .HCLK    (i_periphClk)
  , .HRESETn (i_periphArst_n)
  , .PADDR   (timerPaddr[11:0])
  , .PWDATA  (timerPwdata)
  , .PWRITE  (timerPwrite)
  , .PSEL    (timerPsel)
  , .PENABLE (timerPenable)
  , .PRDATA  (timerPrdata)
  , .PREADY  (timerPready)
  , .PSLVERR (timerPslverr)
  , .irq_o   (o_timerIrq)
  );

  // }}} Timer

  // {{{ GPIO
  // PULP apb_gpio with 32 pads on the periph clock. Pad configuration and
  // the synchronised input copy are not needed by this SoC.

/* verilator lint_off UNUSEDSIGNAL */
  logic [31:0] gpioPaddr;
  logic [3:0]  gpioPstrb;
/* verilator lint_on UNUSEDSIGNAL */
  logic [31:0] gpioPwdata;
  logic        gpioPwrite;
  logic        gpioPsel;
  logic        gpioPenable;
  logic        gpioPready;
  logic        gpioPslverr;
  logic [31:0] gpioPrdata;

/* verilator lint_off PINCONNECTEMPTY */
  apb_gpio
  #(.APB_ADDR_WIDTH (12)
  , .PAD_NUM        (32)
  , .NBIT_PADCFG    (4)
  ) u_gpio
  ( .HCLK            (i_periphClk)
  , .HRESETn         (i_periphArst_n)
  , .dft_cg_enable_i ('0)
  , .PADDR           (gpioPaddr[11:0])
  , .PWDATA          (gpioPwdata)
  , .PWRITE          (gpioPwrite)
  , .PSEL            (gpioPsel)
  , .PENABLE         (gpioPenable)
  , .PRDATA          (gpioPrdata)
  , .PREADY          (gpioPready)
  , .PSLVERR         (gpioPslverr)
  , .gpio_in         (i_gpioIn)
  , .gpio_in_sync    ()
  , .gpio_out        (o_gpioOut)
  , .gpio_dir        (o_gpioDir)
  , .gpio_padcfg     ()
  , .interrupt       (o_gpioInterrupt)
  );
/* verilator lint_on PINCONNECTEMPTY */

  // }}} GPIO

  // {{{ NoC
  // Generated 2x2 mesh: cpu on router 0, ram on router 1, timer on
  // router 2, gpio on router 3.

  nocSoc u_noc
  ( .i_fabricClk    (i_fabricClk)
  , .i_fabricArst_n (i_fabricArst_n)
  , .i_cpuClk       (i_cpuClk)
  , .i_cpuArst_n    (i_cpuArst_n)
  , .i_periphClk    (i_periphClk)
  , .i_periphArst_n (i_periphArst_n)

  , .i_cpuAwaddr    (cpuAwaddr)
  , .i_cpuAwvalid   (cpuAwvalid)
  , .o_cpuAwready   (cpuAwready)
  , .i_cpuWdata     (cpuWdata)
  , .i_cpuWstrb     (cpuWstrb)
  , .i_cpuWvalid    (cpuWvalid)
  , .o_cpuWready    (cpuWready)
  , .o_cpuBresp     (cpuBresp)
  , .o_cpuBvalid    (cpuBvalid)
  , .i_cpuBready    (cpuBready)
  , .i_cpuAraddr    (cpuAraddr)
  , .i_cpuArvalid   (cpuArvalid)
  , .o_cpuArready   (cpuArready)
  , .o_cpuRdata     (cpuRdata)
  , .o_cpuRresp     (cpuRresp)
  , .o_cpuRvalid    (cpuRvalid)
  , .i_cpuRready    (cpuRready)

  , .o_ramAwaddr    (ramAwaddr)
  , .o_ramAwvalid   (ramAwvalid)
  , .i_ramAwready   (ramAwready)
  , .o_ramWdata     (ramWdata)
  , .o_ramWstrb     (ramWstrb)
  , .o_ramWvalid    (ramWvalid)
  , .i_ramWready    (ramWready)
  , .i_ramBresp     (ramBresp)
  , .i_ramBvalid    (ramBvalid)
  , .o_ramBready    (ramBready)
  , .o_ramAraddr    (ramAraddr)
  , .o_ramArvalid   (ramArvalid)
  , .i_ramArready   (ramArready)
  , .i_ramRdata     (ramRdata)
  , .i_ramRresp     (ramRresp)
  , .i_ramRvalid    (ramRvalid)
  , .o_ramRready    (ramRready)

  , .o_timerPaddr   (timerPaddr)
  , .o_timerPwdata  (timerPwdata)
  , .o_timerPwrite  (timerPwrite)
  , .o_timerPstrb   (timerPstrb)
  , .o_timerPsel    (timerPsel)
  , .o_timerPenable (timerPenable)
  , .i_timerPready  (timerPready)
  , .i_timerPslverr (timerPslverr)
  , .i_timerPrdata  (timerPrdata)

  , .o_gpioPaddr    (gpioPaddr)
  , .o_gpioPwdata   (gpioPwdata)
  , .o_gpioPwrite   (gpioPwrite)
  , .o_gpioPstrb    (gpioPstrb)
  , .o_gpioPsel     (gpioPsel)
  , .o_gpioPenable  (gpioPenable)
  , .i_gpioPready   (gpioPready)
  , .i_gpioPslverr  (gpioPslverr)
  , .i_gpioPrdata   (gpioPrdata)
  );

  // }}} NoC

endmodule

`resetall
